def res(q,val,conf,ev,target=None,unc=None,unit=None,ass=None):
    d={'quantity':q,'value':val,'confidence':conf,'evidence':ev}
    if target:d['target']=target
    if unc:d['uncertainty']=unc
    if unit:d['unit']=unit
    if ass:d['assumptions']=ass
    R.append(d)
